5.5 223.6 390.5 230.4 387.3 231.0C384.1 231.6 382.2 228.3 380.0 227.9C377.9 227.6 375.9 231.3 374.3 229.1C372.8 226.9 373.6 219.5 370.7 214.8C367.8 210.1 359.4 203.6 357.0 200.7C354.6 197.8 358.3 198.7 356.4 197.2C354.6 195.6 350.3 192.0 345.7 191.2C341.1 190.4 331.7 194.5 328.8 192.2C326.0 189.9 329.5 180.6 328.6 177.3C327.7 173.9 325.5 172.6 323.3 172.1C321.0 171.6 317.3 174.1 315.1 174.1C313.0 174.2 313.2 171.0 310.5 172.5C307.8 174.0 302.2 181.2 299.1 183.2C296.0 185.1 293.7 182.9 291.9 184.1C290.0 185.2 288.9 190.8 288.0 190.1C287.1 189.5 287.2 182.7 286.4 180.3C285.5 177.9 284.7 175.9 282.9 175.7C281.0 175.6 280.0 178.8 275.1 179.6C270.3 180.4 263.6 184.7 253.7 180.6C243.7 176.5 226.3 161.0 215.5 155.1C204.6 149.2 194.4 146.8 188.7 145.3C183.0 143.7 184.0 146.1 181.2 145.6C178.5 145.1 174.9 143.9 172.2 142.2C169.5 140.6 167.3 135.6 164.9 135.8C162.6 135.9 163.4 141.3 158.2 143.2C152.9 145.0 140.1 147.5 133.4 146.9C126.7 146.2 121.0 141.2 118.2 139.0C115.4 136.9 118.7 136.1 116.7 134.1C114.8 132.1 108.6 128.8 106.6 127.0C104.6 125.1 109.1 124.8 104.8 123.0C100.4 121.2 83.9 119.3 80.7 116.3C77.5 113.3 86.6 109.0 85.7 104.9C84.8 100.8 80.7 96.4 75.4 91.6C70.2 86.9 59.3 79.4 54.0 76.5C48.8 73.6 45.7 74.4 44.0 74.0';
  const RIDGE =
    'M956.0 513.8C947.6 503.1 924.2 462.7 905.8 449.2C887.4 435.7 868.3 446.7 845.6 432.8C822.9 419.0 793.3 394.5 769.3 366.0C745.3 337.5 732.3 283.7 701.6 261.9C670.9 240.1 610.2 233.6 585.2 235.3C560.1 237.1 567.6 264.2 551.4 272.4C535.2 280.5 506.7 289.8 488.1 284.0C469.5 278.2 458.6 246.9 439.6 237.8C420.7 228.6 393.7 240.0 374.3 229.1C354.9 218.2 337.6 178.6 323.3 172.1C308.9 165.6 314.4 196.2 288.0 190.1C261.6 184.1 190.7 143.0 164.9 135.8C139.1 128.6 153.6 157.1 133.4 146.9C113.3 136.6 58.9 86.1 44.0 74.0';
  const SCALE = { km: 10, units: 170.0 }; // 0.0588 km per SVG unit
  const TOWNS = [
    { name: 'Ollantaytambo', x: 142.3, y: 135.6, lat: -13.2586458, lon: -72.2636012, ele: 2846 },
    { name: 'Urubamba', x: 412.3, y: 224.5, lat: -13.305953, lon: -72.1159706, ele: 2872 },
    { name: 'Yucay', x: 469.4, y: 252.9, lat: -13.3210838, lon: -72.0847651, ele: 2858 },
    { name: 'Calca', x: 704.9, y: 254.1, lat: -13.3216818, lon: -71.9560084, ele: 2932 },
    { name: 'Pisac', x: 897.9, y: 440.8, lat: -13.4210472, lon: -71.850496, ele: 2977 },
  ];
  // ─── end generated ───

  /** Label offsets, hand-tuned against the drawn river.
   *
   * Urubamba and Yucay sit ~57 units apart, so one label goes above the river
   * and the other below or they collide. Ollantaytambo and Pisac are the two
   * ends of the drawn reach, where the river runs diagonally straight through
   * where a centred label would sit, so both are pushed off to one side
   * instead of above or below. */
  type LabelOffset = { dx?: number; dy: number; anchor: 'start' | 'middle' | 'end' };
  const LABEL: Record<string, LabelOffset> = {
    Ollantaytambo: { dx: 16, dy: -28, anchor: 'start' },
    Urubamba: { dy: -26, anchor: 'middle' },
    Yucay: { dy: 40, anchor: 'middle' },
    Calca: { dy: -38, anchor: 'middle' },
    Pisac: { dx: -18, dy: 10, anchor: 'end' },
  };

  /** The valley walls are the river's own spine, offset perpendicular to its
   * NW-SE run — so the ridges follow the real valley rather than invented
   * squiggles. Two per side, the outer pair fainter, for depth.
   *
   * Offsets are in SVG units, which SCALE fixes to ~0.059 km each: the inner
   * pair sits ~5 km off the river, the outer ~10 km, which is roughly where the
   * valley walls actually stand. Re-tune these if the frame is refitted. */
  const RIDGES = [
    { dx: 48, dy: -104, opacity: 0.55 },
    { dx: 90, dy: -198, opacity: 0.3 },
    { dx: -48, dy: 104, opacity: 0.55 },
    { dx: -90, dy: 198, opacity: 0.3 },
  ];

  /** Marginalia baseline, kept relative to the generated frame height so a
   * refit never strands the compass and scale bar mid-map. */
  const MARGIN_Y = VIEW.h - 44;

  const HOME = TOWNS.find((t) => t.name === 'Calca')!;
</script>

<figure class="valley">
  <div class="valley-frame">
    <svg
      viewBox="0 0 {VIEW.w} {VIEW.h}"
      class="valley-svg"
      role="img"
      aria-label={m.label}
    >
      <!-- Valley walls -->
      <g fill="none" stroke="var(--color-line-2)" stroke-linecap="round">
        {#each RIDGES as r}
          <path
            d={RIDGE}
            transform="translate({r.dx} {r.dy})"
            stroke-width="1.5"
            opacity={r.opacity}
          />
        {/each}
      </g>

      <!-- Río Vilcanota / Urubamba — the same river, renamed mid-valley -->
      <path
        d={RIVER}
        fill="none"
        stroke="var(--slate)"
        stroke-width="3"
        stroke-linecap="round"
        stroke-linejoin="round"
      />

      <!-- Towns. Calca is the one clay mark in the composition. -->
      {#each TOWNS as town}
        {@const home = town.name === 'Calca'}
        <g>
          {#if home}
            <circle
              cx={town.x}
              cy={town.y}
              r="21"
              fill="none"
              stroke="var(--clay)"
              stroke-width="2"
              opacity="0.45"
            />
          {/if}
          <circle
            cx={town.x}
            cy={town.y}
            r={home ? 9 : 5}
            fill={home ? 'var(--clay)' : 'var(--color-ink-2)'}
          />
          <text
            x={town.x + (LABEL[town.name].dx ?? 0)}
            y={town.y + LABEL[town.name].dy}
            text-anchor={LABEL[town.name].anchor}
            class:home
            class="town-label"
          >
            {town.name}
          </text>
        </g>
      {/each}

      <!-- Compass and scale, bottom-left, quiet -->
      <g class="marginalia">
        <path
          d="M56 {MARGIN_Y} L56 {MARGIN_Y - 34} M56 {MARGIN_Y - 34} L50 {MARGIN_Y - 24}
             M56 {MARGIN_Y - 34} L62 {MARGIN_Y - 24}"
          fill="none"
          stroke="var(--color-ink-2)"
          stroke-width="2"
          stroke-linecap="round"
          opacity="0.6"
        />
        <text x="56" y={MARGIN_Y + 26} text-anchor="middle" class="margin-label">N</text>
        <path
          d="M110 {MARGIN_Y} h{SCALE.units} M110 {MARGIN_Y - 6} v12
             M{110 + SCALE.units} {MARGIN_Y - 6} v12"
          fill="none"
          stroke="var(--color-ink-2)"
          stroke-width="2"
          opacity="0.6"
        />
        <text
          x={110 + SCALE.units / 2}
          y={MARGIN_Y + 26}
          text-anchor="middle"
          class="margin-label"
        >
          {SCALE.km} km
        </text>
      </g>
    </svg>
  </div>

  <figcaption class="valley-caption">
    <span>
      Calca, Valle Sagrado · {Math.abs(HOME.lat).toFixed(4)}° S,
      {Math.abs(HOME.lon).toFixed(4)}° W
    </span>
    <!-- ODbL obligation. Do not remove. -->
    <span class="valley-credit">Map data © OpenStreetMap contributors</span>
  </figcaption>
</figure>

<style>
