  /* Sizes are in SVG user units, not pixels: the frame is 1000 units wide and
   * renders around 560px in the contact grid, so a unit is roughly half a
   * pixel. These look large in the markup and read correctly on screen. */
  .town-label {
    font-family: var(--font-display);
